import{_ as l,b as a,c as t,d as r}from"./chunks/framework.D4cM_aKq.js";const p=JSON.parse('{"title":"让笔记成为自己的知识地图","description":"记录之外，试着建立联系，让学过的知识在需要时重新出现。","frontmatter":{"layout":"article","title":"让笔记成为自己的知识地图","description":"记录之外，试着建立联系，让学过的知识在需要时重新出现。","date":"2026-10-15","category":"学习随笔","directory":"知识整理","tags":["Markdown","知识管理","学习笔记"],"featured":true,"sample":true},"headers":[{"level":2,"title":"从收藏走向理解","slug":"从收藏走向理解","link":"#从收藏走向理解","children":[]},{"level":2,"title":"给知识建立入口","slug":"给知识建立入口","link":"#给知识建立入口","children":[]},{"level":2,"title":"一份可持续的笔记结构","slug":"一份可持续的笔记结构","link":"#一份可持续的笔记结构","children":[]},{"level":2,"title":"允许知识慢慢长出来","slug":"允许知识慢慢长出来","link":"#允许知识慢慢长出来","children":[]},{"level":2,"title":"关联阅读","slug":"关联阅读","link":"#关联阅读","children":[]}],"relativePath":"journal/notes/knowledge-map.md","filePath":"journal/notes/knowledge-map.md"}'),o={name:"journal/notes/knowledge-map.md"};function n(i,e,s,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="从收藏走向理解" tabindex="-1">从收藏走向理解 <a class="header-anchor" href="#从收藏走向理解" aria-label="Permalink to &quot;从收藏走向理解&quot;">​</a></h2><p>保存一篇文章很容易，但收藏本身并不等于理解。可以在记录时，多写一句“这解决了我什么问题”。</p><p>这句话能帮助未来的自己判断，为什么留下了这份资料。</p><h2 id="给知识建立入口" tabindex="-1">给知识建立入口 <a class="header-anchor" href="#给知识建立入口" aria-label="Permalink to &quot;给知识建立入口&quot;">​</a></h2><p>目录像地图上的地区，用稳定的主题归档。标签像地图上的路径，让分散在不同目录的笔记产生联系。</p><p>例如，一篇关于个人站点的文章可以属于“前端开发”，同时拥有“Markdown”和“自动部署”标签。</p><h2 id="一份可持续的笔记结构" tabindex="-1">一份可持续的笔记结构 <a class="header-anchor" href="#一份可持续的笔记结构" aria-label="Permalink to &quot;一份可持续的笔记结构&quot;">​</a></h2><ol><li><strong>问题</strong>：当时想弄清楚什么？</li><li><strong>理解</strong>：用自己的话说明核心概念。</li><li><strong>例子</strong>：给出最小但有意义的实践。</li><li><strong>边界</strong>：什么情况下这个结论不适用？</li><li><strong>关联</strong>：有哪些相关笔记和原始资料？</li></ol><h2 id="允许知识慢慢长出来" tabindex="-1">允许知识慢慢长出来 <a class="header-anchor" href="#允许知识慢慢长出来" aria-label="Permalink to &quot;允许知识慢慢长出来&quot;">​</a></h2><p>不用一开始就设计完整的分类体系。随着笔记增加，再合并重复主题、补充关联链接、修正过时的理解。</p><blockquote><p>整理的目标，是降低下一次理解与使用的成本。</p></blockquote><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><a href="/journal/frontend/digital-study.html">从零搭建一座数字书斋</a></li><li><a href="/projects/tools/note-garden.html">知园 · 笔记整理工具</a></li></ul>',13)])])}const g=l(o,[["render",n]]);export{p as __pageData,g as default};
